[Here](https://github.com/mavlink/MAVSDK/blob/main/src/mavsdk/plugins/action/action_impl.cpp#L451-L456) is the command that MAVSDK sends to the drone for `goto_location()`:

```c++
            command.command = MAV_CMD_DO_REPOSITION;
            command.target_component_id = _system_impl->get_autopilot_id();
            command.params.maybe_param4 = static_cast<float>(to_rad_from_deg(yaw_deg));
            command.params.x = int32_t(std::round(latitude_deg * 1e7));
            command.params.y = int32_t(std::round(longitude_deg * 1e7));
            command.params.maybe_z = altitude_amsl_m;
```

A "denied" result sounds to me like Ardupilot denied this command. Does Ardupilot support `DO_REPOSITION`? Do you have a way to check on the Ardupilot side why the command is denied?

@JonasVautherin Sorry, never done any PR on GitHub so I'm a newbie in that department :-) Here is what I changed and now the `goto_location_async` works fine with ArduCopter SITL:

`void ActionImpl::goto_location_async(
    const double latitude_deg,
    const double longitude_deg,
    const float altitude_amsl_m,
    const float yaw_deg,
    const Action::ResultCallback& callback)
{
    auto send_do_reposition =
        [this, callback, yaw_deg, latitude_deg, longitude_deg, altitude_amsl_m]() {
            MavlinkCommandSender::CommandInt command{};

            command.command = MAV_CMD_DO_REPOSITION;
            command.target_component_id = _system_impl->get_autopilot_id();
            command.params.maybe_param4 = static_cast<float>(to_rad_from_deg(yaw_deg));
            command.params.x = int32_t(std::round(latitude_deg * 1e7));
            command.params.y = int32_t(std::round(longitude_deg * 1e7));
            command.params.maybe_z = altitude_amsl_m;

            _system_impl->send_command_async(
                command, [this, callback](MavlinkCommandSender::Result result, float) {
                    command_result_callback(result, callback);
                });
        };

	if (_system_impl->autopilot() == SystemImpl::Autopilot::Px4) {
        // Change to Hold mode first
		if (_system_impl->get_flight_mode() != FlightMode::Hold) {
			_system_impl->set_flight_mode_async(
				FlightMode::Hold,
				[this, callback, send_do_reposition](MavlinkCommandSender::Result result, float) {
					Action::Result action_result = action_result_from_command_result(result);
					if (action_result != Action::Result::Success) {
						command_result_callback(result, callback);
						return;
					}
					send_do_reposition();
				});
			return;
		}
    } else {
        // Change to Offboard mode first
		if (_system_impl->get_flight_mode() != FlightMode::Offboard) {
			_system_impl->set_flight_mode_async(
				FlightMode::Offboard,
				[this, callback, send_do_reposition](MavlinkCommandSender::Result result, float) {
					Action::Result action_result = action_result_from_command_result(result);
					if (action_result != Action::Result::Success) {
						command_result_callback(result, callback);
						return;
					}
					send_do_reposition();
				});
			return;
		}
    }    

    send_do_reposition();
}`

